export type ButtonVariants = VariantProps<typeof buttonVariants>;

export type ButtonProps = UIProps<React.ComponentProps<typeof ButtonPrimitive>> &
  VariantProps<typeof buttonVariants> &
  SharedProps & {
    icon?: React.ReactNode;
    isLoading?: boolean | undefined;
  };
function Button({
  className,
  variant,
  size,
  icon,
  isLoading = false,
  disabled,
  children,
  testId,
  type = 'button',
  ...props
}: ButtonProps) {
  const renderChildren = typeof children === 'function' ? children : () => children;
  const renderedIcon = isLoading === true ? <Spinner /> : icon;
  return (
    <ButtonPrimitive
      {...definedProps(props)}
      aria-busy={isLoading === true || undefined}
      className={(state) =>
        cn(buttonVariants({ variant, size }), typeof className === 'function' ? className(state) : className)
      }
      data-testid={testId ?? props['data-testid']}
      disabled={disabled === true || isLoading === true}
      type={type}
    >
      {(state) => (
        <>
          {renderedIcon}
          {renderChildren(state)}
        </>
      )}
    </ButtonPrimitive>
  );
}

export { Button, buttonVariants };

'use client';
import {
  CalendarDay as CalendarDayPrimitive,
  CalendarGrid as CalendarGridPrimitive,
  CalendarHeading as CalendarHeadingPrimitive,
  CalendarNext as CalendarNextPrimitive,
  CalendarPrevious as CalendarPreviousPrimitive,
  CalendarWeekday as CalendarWeekdayPrimitive,
  CalendarWeekdays as CalendarWeekdayPrimitives,
  CalendarWeeks as CalendarWeeksPrimitive,
  Calendar as SDKCalendar,
} from '@ui-sdk/react/calendar';
import type React from 'react';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

export {
  CalendarDay,
  CalendarGrid,
  CalendarHeading,
  CalendarMonthSelect,
  CalendarNext,
  CalendarPrevious,
  CalendarWeekday,
  CalendarWeekdays,
  CalendarWeeks,
  CalendarYearSelect,
  createCalendarController,
} from '@ui-sdk/react/calendar';
export function Calendar({ className, children, ...props }: React.ComponentProps<typeof SDKCalendar>) {
  return (
    <SDKCalendar
      {...props}
      className={(state) =>
        cn(
          'w-fit rounded-lg border border-border bg-background p-3 text-sm',
          typeof className === 'function' ? className(state) : className
        )
      }
    >
      {children ?? (
        <>
          <div className="flex items-center justify-between gap-2">
            <CalendarPreviousPrimitive aria-label="Previous month" className="size-8 rounded-md hover:bg-muted">
              ‹
            </CalendarPreviousPrimitive>
            <CalendarHeadingPrimitive className="font-medium" />
            <CalendarNextPrimitive aria-label="Next month" className="size-8 rounded-md hover:bg-muted">
              ›
            </CalendarNextPrimitive>
          </div>
          <CalendarGridPrimitive className="w-full border-collapse">
            <CalendarWeekdayPrimitives>
              {(index) => (
                <CalendarWeekdayPrimitive className="size-8 text-xs font-normal text-muted-foreground" index={index} />
              )}
            </CalendarWeekdayPrimitives>
            <CalendarWeeksPrimitive>
              {(cell) => (
                <CalendarDayPrimitive
                  className="size-8 cursor-pointer rounded-md text-center outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring data-outside:opacity-50 data-selected:bg-primary data-selected:text-primary-foreground data-unavailable:opacity-50"
                  value={cell.date}
                />
              )}
            </CalendarWeeksPrimitive>
          </CalendarGridPrimitive>
        </>
      )}
    </SDKCalendar>
  );
}

import { cva, type VariantProps } from 'class-variance-authority';
import { type MotionProps, motion } from 'motion/react';
import React from 'react';

import { Heading, Text } from '@/components/ui/typography/index';
import { cn } from '@/registry/base-nova/protoform/lib/utils';
import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

const cardVariants = cva(
  'flex min-w-0 flex-col rounded-lg border border-solid border-border bg-card text-card-foreground',
  {
    defaultVariants: {
      size: 'md',
      variant: 'elevated',
    },
    variants: {
      size: {
        default: 'max-w-md gap-4 px-8 py-6',
        full: 'w-full gap-4 px-8 py-6',
        lg: 'max-w-lg gap-4 px-10 py-8',
        md: 'max-w-md gap-4 px-8 py-6',
        sm: 'max-w-sm gap-2 px-6 py-4',
        xl: 'max-w-xl gap-6 px-12 py-10',
      },
      variant: {
        choice:
          'rounded-md border-2 border-solid p-4 shadow-none transition-all group-data-[state=checked]:!border-selected hover:shadow-lg',
        elevated: 'shadow-lg',
        ghost: 'border-0 bg-transparent shadow-none dark:bg-transparent',
        outlined: 'border-1',
        standard: '',
      },
    },
  }
);

export type CardVariant = VariantProps<typeof cardVariants>['variant'];
export type CardSize = VariantProps<typeof cardVariants>['size'];

type BaseCardProps = SharedProps & {
  size?: CardSize;
  variant?: CardVariant;
  className?: string | undefined;
};

type StaticCardProps = BaseCardProps & Omit<React.ComponentProps<'div'>, keyof BaseCardProps> & { animated?: false };
type AnimatedCardProps = BaseCardProps & Omit<MotionProps, keyof BaseCardProps> & { animated: true };

export type CardProps = StaticCardProps | AnimatedCardProps;

const Card = React.forwardRef<HTMLDivElement, CardProps>(({ className, size, variant, testId, ...props }, ref) => {
  const cardClassName = cn(cardVariants({ size, variant }), className);

  if (props.animated === true) {
    const { animated: _animated, ...motionProps } = props;
    return <motion.div className={cardClassName} data-slot="card" data-testid={testId} ref={ref} {...motionProps} />;
  }

  const { animated: _animated, ...staticProps } = props;
  return <div className={cardClassName} data-slot="card" data-testid={testId} ref={ref} {...staticProps} />;
});

Card.displayName = 'Card';

const cardHeaderVariants = cva(
  '@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6',
  {
    defaultVariants: {
      padding: 'none',
      spacing: 'normal',
    },
    variants: {
      padding: {
        lg: 'px-8',
        md: 'px-6',
        none: '',
        sm: 'px-3',
      },
      spacing: {
        loose: 'gap-2',
        normal: 'gap-1.5',
        tight: 'gap-1',
      },
    },
  }
);

interface CardHeaderProps extends React.ComponentProps<'div'>, VariantProps<typeof cardHeaderVariants>, SharedProps {}

const CardHeader = React.forwardRef<HTMLDivElement, CardHeaderProps>(
  ({ className, spacing, padding, testId, ...props }, ref) => (
    <div
      className={cn(cardHeaderVariants({ padding, spacing }), className)}
      data-slot="card-header"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

CardHeader.displayName = 'CardHeader';

const CardTitle = React.forwardRef<
  HTMLHeadingElement,
  React.ComponentProps<'div'> & SharedProps & { level?: 1 | 2 | 3 | 4; spacing?: 'loose' }
>(({ className, level = 4, spacing, testId, children, ...props }, ref) => {
  let content: React.ReactNode = null;
  if (children) {
    content = typeof children === 'string' ? <Heading level={level}>{children}</Heading> : children;
  }

  return (
    <div
      className={cn(spacing === 'loose' && 'gap-3', className)}
      data-slot="card-title"
      data-testid={testId}
      ref={ref}
      {...props}
    >
      {content}
    </div>
  );
});

CardTitle.displayName = 'CardTitle';

const CardDescription = React.forwardRef<HTMLDivElement, React.ComponentProps<'div'> & SharedProps>(
  ({ className, testId, children, ...props }, ref) => {
    let content: React.ReactNode = null;
    if (children) {
      content = typeof children === 'string' ? <Text>{children}</Text> : children;
    }

    return (
      <div
        className={cn('text-sm text-muted-foreground', className)}
        data-slot="card-description"
        data-testid={testId}
        ref={ref}
        {...props}
      >
        {content}
      </div>
    );
  }
);

