function CodeBlockCopyButton(props: React.ComponentProps<typeof Button> & { value: string }) {
  return <CodeBlockCopyControl key={props.value} {...props} />;
}

function CodeBlockCopyControl({
  value,
  variant = 'ghost',
  size = 'icon-xs',
  className,
  onClick,
  type = 'button',
  ...props
}: React.ComponentProps<typeof Button> & { value: string }) {
  const [copied, setCopied] = React.useState(false);
  const [copyError, setCopyError] = React.useState(false);

  React.useEffect(
    function resetCopyFeedback() {
      if (copied !== true) {
        return;
      }

      const timeout = setTimeout(() => setCopied(false), 2000);
      return () => clearTimeout(timeout);
    },
    [copied]
  );

  return (
    <>
      <Button
        aria-label={copied === true ? 'Copied' : 'Copy'}
        className={className}
        data-copied={copied === true || undefined}
        data-slot="code-block-copy-button"
        onClick={async (event, details) => {
          onClick?.(event, details);
          if (event.defaultPrevented) {
            return;
          }
          setCopyError(false);
          try {
            await navigator.clipboard.writeText(value);
            setCopied(true);
          } catch {
            setCopyError(true);
            setCopied(false);
          }
        }}
        size={size}
        type={type}
        variant={variant}
        {...props}
      >
        {copied === true ? <CheckIcon /> : <CopyIcon />}
      </Button>
      <span aria-live="polite" className="sr-only">
        {copied === true ? 'Copied' : ''}
      </span>
      {copyError === true ? (
        <span className="text-xs text-destructive" role="alert">
          Could not copy code. Try again.
        </span>
      ) : null}
    </>
  );
}

