  const dataProps = props as Record<string, unknown>;
  const invalid = dataProps['data-invalid'] === true || dataProps['data-invalid'] === 'true';
  const errorId = useId();
  const ctx = useMemo(() => ({ errorId: invalid ? errorId : undefined, invalid }), [invalid, errorId]);

  return (
