        disabled,
      })}
      items={options.map((option) => ({ ...option, disabled: option.disabled ?? false }))}
      onValueChange={(next) => onChange(next ?? '')}
      status={loading === true ? 'loading' : 'idle'}
      value={value ?? null}
      {...(filter === true ? {} : { filter: false })}
    >
      <div className={cn('relative', className)}>
        <SearchIcon
          aria-hidden="true"
          className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
        />
        <ComboboxInput
          {...definedProps(inputProps)}
          placeholder={placeholder}
          testId={inputTestId ?? testId}
          variant="search"
        />
        {clearable === true ? (
          <ComboboxClear aria-label="Clear selection" className="absolute top-1/2 right-2 -translate-y-1/2">
            <XIcon aria-hidden="true" className="size-3.5" />
          </ComboboxClear>
        ) : null}
      </div>
      <ComboboxContent>
        <ComboboxList>
          {groups === undefined
            ? renderOptions(options)
            : groups.map((group) => (
                <ComboboxGroup key={group.heading}>
                  <ComboboxGroupLabel testId={group.testId}>{group.heading}</ComboboxGroupLabel>
                  {renderOptions(group.options)}
                </ComboboxGroup>
              ))}
          {creatable === true ? (
            <ComboboxCreate
              onCreate={(query) => {
                onCreateOption?.(query);
                onChange(query);
                return query;
              }}
            >
              {(state) => `${createLabel} ${state.query}`}
            </ComboboxCreate>
          ) : null}
        </ComboboxList>
        {loading === true ? <ComboboxStatus>Loading…</ComboboxStatus> : <ComboboxEmpty>{emptyState}</ComboboxEmpty>}
      </ComboboxContent>
    </Combobox>
  );
}

export type UIProps<T> = { [K in keyof T]: T[K] | (Pick<T, K> extends Required<Pick<T, K>> ? never : undefined) };
type DefinedProps<T> = {
  [K in keyof T as undefined extends T[K] ? never : K]: T[K];
} & {
  [K in keyof T as undefined extends T[K] ? K : never]?: Exclude<T[K], undefined>;
};
function hasDefinedValues<T extends object>(props: T): props is T & DefinedProps<T> {
  return Reflect.ownKeys(props).every((key) => Reflect.get(props, key) !== undefined);
}
export function definedProps<T extends object>(props: T): DefinedProps<T> {
  const result = { ...props };
  for (const key of Reflect.ownKeys(result)) {
    if (Reflect.get(result, key) === undefined) {
      Reflect.deleteProperty(result, key);
    }
  }
  if (hasDefinedValues(result)) {
    return result;
  }
  throw new TypeError('Could not normalize UI properties.');
}

